#!/usr/bin/env python3
from __future__ import annotations
import argparse,json
from pathlib import Path

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--review-a',type=Path,required=True); ap.add_argument('--review-b',type=Path,required=True); ap.add_argument('--output',type=Path,required=True); args=ap.parse_args(); a={x['sample_id']:x for x in json.loads(args.review_a.read_text()).get('samples',[])}; b={x['sample_id']:x for x in json.loads(args.review_b.read_text()).get('samples',[])}; rows=[]
    for sid in sorted(set(a)|set(b)):
        ra,rb=a.get(sid,{}),b.get(sid,{}); same_domain=ra.get('review_domain') and ra.get('review_domain')==rb.get('review_domain'); same_answer=ra.get('review_answerability') and ra.get('review_answerability')==rb.get('review_answerability'); ai_review=(str(json.loads(args.review_a.read_text()).get('review_mode','')).startswith('ai') or str(json.loads(args.review_b.read_text()).get('review_mode','')).startswith('ai')); status='ai-consensus-provisional' if same_domain and same_answer and ai_review else 'consensus' if same_domain and same_answer else 'disagreement'; rows.append({'sample_id':sid,'split':ra.get('split',rb.get('split','')),'review_a':{'domain':ra.get('review_domain',''),'answerability':ra.get('review_answerability',''),'confidence':ra.get('review_confidence','')},'review_b':{'domain':rb.get('review_domain',''),'answerability':rb.get('review_answerability',''),'confidence':rb.get('review_confidence','')},'status':status,'consensus_domain':ra.get('review_domain','') if status=='consensus' else '','consensus_answerability':ra.get('review_answerability','') if status=='consensus' else ''})
    result={'name':'domain-calibration-review-reconciliation','reviewers':{'a':json.loads(args.review_a.read_text()).get('reviewer_name',''),'b':json.loads(args.review_b.read_text()).get('reviewer_name','')},'samples':rows,'counts':{'consensus':sum(r['status']=='consensus' for r in rows),'ai_consensus_provisional':sum(r['status']=='ai-consensus-provisional' for r in rows),'disagreement':sum(r['status']=='disagreement' for r in rows)},'status':'pending-adjudication' if any(r['status']=='disagreement' for r in rows) else 'ai-consensus-provisional' if any(r['status']=='ai-consensus-provisional' for r in rows) else 'consensus-ready','warning':'Consensus requires independent reviewer identities and adjudication of every disagreement.'}; args.output.write_text(json.dumps(result,indent=2)+'\n'); print(json.dumps(result['counts'],indent=2))
if __name__=='__main__': main()
